	@Test
	void fixedVariablesKeepTheirRdfTermAndType() {
		for (Value value : List.of(VF.createLiteral(7), VF.createLiteral(""), VF.createIRI("urn:successful-value"),
				VF.createLiteral("word", "en"), VF.createLiteral("invalid", XSD.BOOLEAN))) {
			QueryBindingSet bindings = new QueryBindingSet();
			bindings.addBinding("x", value);
			ReadOnlyContext fixed = QueryAlgebraBindingAnalysis.withBindingValues(new SingletonSet(), bindings)
					.rootContext();
			Simplification result = simplifier.simplify(Var.of("x"), fixed);
			assertThat(result.condition()).isInstanceOf(ValueConstant.class);
			assertThat(((ValueConstant) result.condition()).getValue()).isEqualTo(value);
			assertThat(result.outcomes()).containsExactly(outcome(new ValueConstant(value), bindings));
		}
	}

	@Test
	void logicalOperatorsUseTheCompleteSparqlErrorTables() {
		List<ValueExpr> arguments = List.of(bool(true), bool(false), Var.of("absent"), iri());
		for (ValueExpr left : arguments) {
			for (ValueExpr right : arguments) {
				for (ValueExpr expression : List.of(new And(left.clone(), right.clone()),
						new Or(left.clone(), right.clone()))) {
					Simplification result = simplify(expression);
					EbvOutcome expected = outcome(expression, EmptyBindingSet.getInstance());
					assertThat(result.outcomes()).as(expression.toString()).containsExactly(expected);
					assertThat(outcome(result.condition(), EmptyBindingSet.getInstance()))
							.as(expression.toString())
							.isEqualTo(expected);
				}
			}
		}
	}

	@Test
	void nestedFalseOrErrorNeverBecomesAnUnconditionalFalseValue() {
		ReadOnlyContext possible = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(new SingletonSet(),
				analysis.rootContext(), Set.of("x")).rootContext();
		ValueExpr falseOrError = new And(new Bound(Var.of("x")), Var.of("absent"));
		Simplification inner = simplifier.simplify(falseOrError, possible);
		assertThat(inner.verdict()).isEqualTo(FilterVerdict.ALWAYS_REJECTS);
		assertThat(inner.outcomes()).containsExactlyInAnyOrder(EbvOutcome.FALSE, EbvOutcome.ERROR);
		assertThat(inner.condition()).isNotInstanceOf(ValueConstant.class);
		for (ValueExpr expression : List.of(new Not(falseOrError.clone()),
				new If(falseOrError.clone(), bool(false), bool(true)))) {
			Simplification result = simplifier.simplify(expression, possible);
			assertThat(result.outcomes()).containsExactlyInAnyOrder(EbvOutcome.TRUE, EbvOutcome.ERROR);
			assertThat(result.verdict()).isEqualTo(FilterVerdict.UNKNOWN);
			assertThat(outcome(result.condition(), EmptyBindingSet.getInstance())).isEqualTo(EbvOutcome.TRUE);
			assertThat(outcome(result.condition(), bindings("x", VF.createLiteral(1))))
					.isEqualTo(EbvOutcome.ERROR);
		}
	}

