	@Test
	void existsUsesOnlyProvenEmptinessOrUnitExistence() {
		assertThat(simplify(new Exists(new EmptySet())).verdict()).isEqualTo(FilterVerdict.ALWAYS_REJECTS);
		assertThat(simplify(new Not(new Exists(new EmptySet()))).verdict()).isEqualTo(FilterVerdict.ALWAYS_TRUE);
		assertThat(simplify(new Exists(new SingletonSet())).verdict()).isEqualTo(FilterVerdict.ALWAYS_TRUE);
		assertThat(simplify(new Exists(new Union(new EmptySet(), new Union(new EmptySet(), new EmptySet()))))
				.verdict()).isEqualTo(FilterVerdict.ALWAYS_REJECTS);
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		assertThat(analysis.outputFacts(pattern, analysis.rootContext()).canProduceRows()).isTrue();
		Simplification possible = simplify(new Exists(pattern));
		assertThat(possible.verdict()).isEqualTo(FilterVerdict.UNKNOWN);
		assertThat(possible.condition()).isInstanceOf(Exists.class);
		assertThat(simplify(new Exists(new Union(new EmptySet(), pattern.clone()))).verdict())
				.isEqualTo(FilterVerdict.UNKNOWN);
	}

	@Test
	void correlatedExistsBindingsAreRetainedAndNeverEvaluatedDuringPlanning() {
		StatementPattern pattern = new StatementPattern(Var.of("x"), Var.of("p"), Var.of("o"));
		Exists expression = new Exists(new Filter(pattern, new Bound(Var.of("x"))));
		ReadOnlyContext input = QueryAlgebraBindingAnalysis
				.withBindingValues(new SingletonSet(), bindings("x", VF.createIRI("urn:correlated")))
				.rootContext();
		EvaluationStrategy noDatasetAccess = new DefaultEvaluationStrategy(new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
					Resource... contexts) {
				throw new AssertionError("EXISTS must never query a dataset during simplification");
			}
		}, null);
		Simplification result = new FilterConditionSimplifier(analysis, noDatasetAccess).simplify(expression, input);
		assertThat(result.verdict()).isEqualTo(FilterVerdict.UNKNOWN);
		assertThat(result.condition()).isEqualTo(expression);
	}

	@Test
	void existsCannotSuppressQueryFatalOrVolatileSubqueries() {
		Service service = new Service(Var.of("service", VF.createIRI("urn:service")), new EmptySet(), "{}", Map.of(),
				null, false);
		assertThat(simplify(new Exists(new Join(new EmptySet(), service))).verdict()).isEqualTo(FilterVerdict.UNKNOWN);
		CountingFunction function = new CountingFunction("urn:simplifier:exists", Function.Determinism.VOLATILE, false);
		withRegistered(function, () -> {
			Extension effect = new Extension(new SingletonSet(),
					new ExtensionElem(new FunctionCall(function.getURI()), "effect"));
			Simplification result = simplify(new Exists(new Join(new EmptySet(), effect)));
			assertThat(result.verdict()).isEqualTo(FilterVerdict.UNKNOWN);
			assertThat(function.calls).hasValue(0);
		});
	}

	@Test
	void unreachableFunctionArgumentsAreNeverInvokedDuringSimplification() {
		CountingFunction function = new CountingFunction("urn:simplifier:unreachable",
				Function.Determinism.DETERMINISTIC, false);
		withRegistered(function, () -> {
			for (ValueExpr expression : List.of(new Or(bool(true), new FunctionCall(function.getURI())),
					new And(bool(false), new FunctionCall(function.getURI())),
					new If(bool(true), bool(true), new FunctionCall(function.getURI())),
					new If(bool(false), new FunctionCall(function.getURI()), bool(true)),
					new If(iri(), new FunctionCall(function.getURI()), new FunctionCall(function.getURI())),
					new Coalesce(List.of(iri(), new FunctionCall(function.getURI()))),
					new Compare(Var.of("absent"), new FunctionCall(function.getURI()), Compare.CompareOp.EQ))) {
				simplify(expression);
				assertThat(function.calls).as(expression.toString()).hasValue(0);
			}
		});
	}

	@Test
	void reachableVolatileAndFreshFunctionsRetainTheirEffectsUnderBothPolicies() {
		for (QueryExecutionPolicy policy : List.of(QueryExecutionPolicy.DEFAULT, QueryExecutionPolicy.EXPERIMENTAL)) {
			for (CountingFunction function : List.of(
					new CountingFunction("urn:simplifier:volatile", Function.Determinism.VOLATILE, false),
					new CountingFunction("urn:simplifier:fresh", Function.Determinism.DETERMINISTIC, true))) {
				withRegistered(function, () -> {
					FilterConditionSimplifier active = new FilterConditionSimplifier(analysis,
							strategy(QueryEvaluationMode.STRICT, policy));
					for (ValueExpr expression : List.of(new Or(new FunctionCall(function.getURI()), bool(true)),
							new And(new FunctionCall(function.getURI()), bool(false)),
							new Not(new And(new FunctionCall(function.getURI()), bool(false))),
							new If(new Or(new FunctionCall(function.getURI()), bool(true)), bool(true), bool(false)),
							new Coalesce(
									List.of(new And(new FunctionCall(function.getURI()), bool(false)), bool(true))))) {
						Simplification result = active.simplify(expression, analysis.rootContext());
						assertThat(result.verdict()).isEqualTo(FilterVerdict.UNKNOWN);
						assertThat(functionCalls(result.condition())).hasSize(1);
						assertThat(function.calls).hasValue(0);
					}
				});
			}
		}
	}

	@Test
	void functionFoldingPreservesTheActualExecutionPolicy() {
		CountingFunction function = new CountingFunction("urn:simplifier:policy", Function.Determinism.UNSPECIFIED,
				false);
		withRegistered(function, () -> {
			assertThat(simplify(new FunctionCall(function.getURI())).verdict()).isEqualTo(FilterVerdict.UNKNOWN);
			assertThat(function.calls).hasValue(0);
			EvaluationStrategy defaultPolicy = strategy(QueryEvaluationMode.STRICT, QueryExecutionPolicy.DEFAULT);
			Simplification folded = new FilterConditionSimplifier(analysis, defaultPolicy)
					.simplify(new FunctionCall(function.getURI()), analysis.rootContext());
			assertThat(folded.verdict()).isEqualTo(FilterVerdict.ALWAYS_TRUE);
			assertThat(function.calls).hasValue(1);
		});
	}

